    11	/** Re-renders once a second so relative clocks stay live. */
    12	function useTick(active: boolean) {
    13	  const [, setTick] = useState(0);
    14	
    15	  useEffect(() => {
    16	    if (!active) return;
    17	    const id = window.setInterval(() => setTick((t) => t + 1), 1000);
    18	    return () => window.clearInterval(id);
    19	  }, [active]);
    20	}
    21	
    22	/**
    23	 * Elapsed workout time and rest countdown, refreshed every second while the
    24	 * session runs. Both values are derived from timestamps, so nothing drifts.
    25	 */
    26	export function useSessionClock() {
    27	  const status = useSessionStore((s) => s.status);
    28	  const accumulatedMs = useSessionStore((s) => s.accumulatedMs);
    29	  const runningSince = useSessionStore((s) => s.runningSince);
    30	  const rest = useSessionStore((s) => s.rest);
    31	
    32	  useTick(status === "running");
    33	
    34	  const remaining = rest ? remainingOf(rest) : null;
    35	  const total = rest ? rest.durationSeconds * 1000 : 0;
    36	
    37	  return {
    38	    status,
    39	    elapsedMs: sessionElapsedMs({ accumulatedMs, runningSince }),
    40	    restRemainingMs: remaining,
    41	    /** 0 at the start of a rest, 1 when it is over. */
    42	    restProgress: remaining !== null && total > 0 ? 1 - remaining / total : 0,
    43	  };
    44	}
