     1	import type { ExerciseCategory, Workout, WorkoutExercise } from "@/types/workout";
     2	
     3	/* ── Session ordering ── */
     4	
     5	/** Where a session currently is / where it goes next. */
     6	export type SessionStep = {
     7	  exerciseId: string;
     8	  setNumber: number;
     9	};
    10	
    11	const PHASE_ORDER: Record<ExerciseCategory, number> = {
    12	  WARMUP: 0,
    13	  MAIN: 1,
    14	  STRETCHING: 2,
    15	};
    16	
    17	/** `sortOrder` restarts per phase, so phase has to be the primary key. */
    18	export function orderedExercises(workout: Workout): WorkoutExercise[] {
    19	  return [...workout.exercises].sort(
    20	    (a, b) =>
    21	      PHASE_ORDER[a.phase] - PHASE_ORDER[b.phase] || a.sortOrder - b.sortOrder,
    22	  );
    23	}
    24	
    25	export function exerciseById(
    26	  workout: Workout | null,
    27	  exerciseId: string | null | undefined,
    28	): WorkoutExercise | null {
    29	  if (!workout || !exerciseId) return null;
    30	  return workout.exercises.find((ex) => ex.id === exerciseId) ?? null;
    31	}
    32	
    33	/** An exercise with no target still counts as one set — never zero. */
    34	export const targetSetCount = (exercise: WorkoutExercise) =>
    35	  Math.max(exercise.targetSets || 0, 1);
    36	
    37	/** The plan leaves warmups without rest, but they still need a breather. */
    38	export const WARMUP_REST_SECONDS = 60;
    39	
    40	/**
    41	 * Rest after a set. Uses the planned value, falling back to a short default
    42	 * for warmups (every warmup row stores 0) and to none for everything else.
    43	 */
    44	export function restSecondsFor(exercise: WorkoutExercise): number {
    45	  const planned = exercise.restSeconds ?? 0;
    46	  if (planned > 0) return planned;
    47	  return exercise.phase === "WARMUP" ? WARMUP_REST_SECONDS : 0;
    48	}
    49	
    50	const isPending = (exercise: WorkoutExercise, skipped: string[]) =>
    51	  !skipped.includes(exercise.id) &&
    52	  exercise.sets.length < targetSetCount(exercise);
    53	
    54	const stepFor = (exercise: WorkoutExercise): SessionStep => ({
    55	  exerciseId: exercise.id,
    56	  setNumber: exercise.sets.length + 1,
    57	});
    58	
    59	function nextPending(
    60	  ordered: WorkoutExercise[],
    61	  from: number,
    62	  skipped: string[],
    63	): SessionStep | null {
    64	  for (let i = Math.max(from, 0); i < ordered.length; i += 1) {
    65	    if (isPending(ordered[i], skipped)) return stepFor(ordered[i]);
    66	  }
    67	  return null;
    68	}
    69	
    70	/** Entry point for a fresh or resumed session — earliest unfinished exercise. */
    71	export function firstStep(
    72	  workout: Workout,
    73	  skipped: string[] = [],
    74	): SessionStep | null {
    75	  return nextPending(orderedExercises(workout), 0, skipped);
    76	}
    77	
    78	/**
    79	 * Where logging a set leads. `loggedAfter` is the exercise's set count
    80	 * *including* the set just saved, so this works before the refetch lands.
    81	 */
    82	export function stepAfterSet(
    83	  workout: Workout,
    84	  exerciseId: string,
    85	  loggedAfter: number,
    86	  skipped: string[] = [],
    87	): SessionStep | null {
    88	  const ordered = orderedExercises(workout);
    89	  const index = ordered.findIndex((ex) => ex.id === exerciseId);
    90	  if (index === -1) return firstStep(workout, skipped);
    91	
    92	  if (loggedAfter < targetSetCount(ordered[index])) {
    93	    return { exerciseId, setNumber: loggedAfter + 1 };
    94	  }
    95	
    96	  return nextPending(ordered, index + 1, skipped);
    97	}
    98	
    99	/**
   100	 * Where moving past an exercise leads — skipping it, or marking it done.
   101	 * `excluded` is the union of skipped and completed ids.
   102	 */
   103	export function stepAfterExercise(
   104	  workout: Workout,
   105	  exerciseId: string,
   106	  excluded: string[] = [],
   107	): SessionStep | null {
   108	  const ordered = orderedExercises(workout);
   109	  const index = ordered.findIndex((ex) => ex.id === exerciseId);
   110	  return nextPending(ordered, index + 1, excluded);
   111	}
   112	
   113	/* ── Display ── */
   114	
   115	/** `m:ss` under an hour, `h:mm:ss` above it. */
   116	export function formatSessionTime(ms: number): string {
   117	  const total = Math.max(Math.floor(ms / 1000), 0);
   118	  const hours = Math.floor(total / 3600);
   119	  const minutes = Math.floor((total % 3600) / 60);
   120	  const seconds = total % 60;
   121	
   122	  if (hours > 0) {
   123	    return `${hours}:${String(minutes).padStart(2, "0")}:${String(seconds).padStart(2, "0")}`;
   124	  }
   125	  return `${minutes}:${String(seconds).padStart(2, "0")}`;
   126	}
