    10	export function formatSetReps(reps: number | null): string | undefined {
    11	  if (reps === null) return undefined;
    12	  return String(reps);
    13	}
    14	
    15	export function formatSetTime(durationSeconds: number | null): string | undefined {
    16	  if (durationSeconds === null) return undefined;
    17	  if (durationSeconds >= 60) {
    18	    return `${Math.round(durationSeconds / 60)} min`;
    19	  }
    20	  return `${durationSeconds} s`;
    21	}
    22	
    23	export function formatSetDistance(distance: number | null): string | undefined {
    24	  if (distance === null) return undefined;
    25	  return `${distance} km`;
    26	}
    27	
    28	/** One-line summary of a logged set, e.g. "60 kg · 10 · 3 km". */
    29	export function formatSetSummary(set: WorkoutSet): string {
    30	  return [
    31	    formatSetWeight(set.weight),
    32	    formatSetReps(set.reps),
    33	    formatSetTime(set.durationSeconds),
    34	    formatSetDistance(set.distance),
    35	    set.notes ?? undefined,
    36	  ]
    37	    .filter(Boolean)
    38	    .join(" · ");
    39	}

