import type {
  AlternateMuscle,
  ExerciseCategory,
  ExerciseType,
  MeasurementType,
  MuscleGroup,
  Workout,
  WorkoutExercise,
  WorkoutSet,
  WorkoutSetInput,
} from "@/types/workout";

import { MOCK_FAIL } from "./config";

/* ── Exercise library ── */

type LibraryEntry = {
  exerciseId: string;
  name: string;
  primaryMuscle: MuscleGroup;
  secondaryMuscles: MuscleGroup[];
  exerciseType: ExerciseType;
  measurementType: MeasurementType;
  targetReps: string | null;
  targetDurationSeconds: number | null;
  restSeconds: number | null;
  instructions: string;
};

const LIBRARY = {
  armCircles: {
    exerciseId: "ex-arm-circles",
    name: "Arm Circles",
    primaryMuscle: "SHOULDERS",
    secondaryMuscles: [],
    exerciseType: "ISOLATION",
    measurementType: "DURATION",
    targetReps: null,
    targetDurationSeconds: 30,
    restSeconds: 0,
    instructions:
      "Stand tall with arms out to the sides\nDraw small circles, then widen them\nKeep the shoulders down, away from the ears\nSwitch direction halfway through",
  },
  benchPress: {
    exerciseId: "ex-barbell-bench-press",
    name: "Barbell Bench Press",
    primaryMuscle: "CHEST",
    secondaryMuscles: ["TRICEPS", "SHOULDERS"],
    exerciseType: "COMPOUND",
    measurementType: "REPS",
    targetReps: "8-12",
    targetDurationSeconds: null,
    restSeconds: 90,
    instructions:
      "Set up: feet planted, shoulder blades pinned\nGrip just outside shoulder width\nLower to the chest with control\nDrive up without bouncing\nReset your stance between reps",
  },
  inclinePress: {
    exerciseId: "ex-incline-dumbbell-press",
    name: "Incline Dumbbell Press",
    primaryMuscle: "CHEST",
    secondaryMuscles: ["SHOULDERS"],
    exerciseType: "COMPOUND",
    measurementType: "REPS",
    targetReps: "10-12",
    targetDurationSeconds: null,
    restSeconds: 90,
    instructions:
      "Set the bench to 30 degrees\nStart with the dumbbells at chest height\nPress up and slightly together\nLower slowly until you feel the stretch",
  },
  treadmill: {
    exerciseId: "ex-treadmill-intervals",
    name: "Treadmill Intervals",
    primaryMuscle: "LEGS",
    secondaryMuscles: ["CALVES"],
    exerciseType: "CARDIO",
    measurementType: "DURATION",
    targetReps: null,
    targetDurationSeconds: 300,
    restSeconds: 60,
    instructions:
      "Start with two minutes at an easy pace\nAlternate one minute fast, one minute easy\nLand mid-foot, keep the strides short\nCool down for the last minute",
  },
  chestStretch: {
    exerciseId: "ex-chest-stretch",
    name: "Doorway Chest Stretch",
    primaryMuscle: "CHEST",
    secondaryMuscles: ["SHOULDERS"],
    exerciseType: "ISOLATION",
    measurementType: "DURATION",
    targetReps: null,
    targetDurationSeconds: 45,
    restSeconds: 0,
    instructions:
      "Place a forearm on the door frame\nStep through until you feel the stretch\nHold without bouncing\nBreathe out as you lean in",
  },
  legPress: {
    exerciseId: "ex-leg-press",
    name: "Leg Press",
    primaryMuscle: "LEGS",
    secondaryMuscles: ["GLUTES"],
    exerciseType: "COMPOUND",
    measurementType: "REPS",
    targetReps: "10-12",
    targetDurationSeconds: null,
    restSeconds: 120,
    instructions:
      "Feet shoulder width on the platform\nLower until the knees reach 90 degrees\nPress through the whole foot\nStop just short of locking out",
  },
  hamstringCurl: {
    exerciseId: "ex-hamstring-curl",
    name: "Seated Hamstring Curl",
    primaryMuscle: "HAMSTRINGS",
    secondaryMuscles: ["CALVES"],
    exerciseType: "ISOLATION",
    measurementType: "REPS",
    targetReps: "12-15",
    targetDurationSeconds: null,
    restSeconds: 75,
    instructions:
      "Line the knee up with the pivot\nCurl until the pad is under the seat\nSqueeze for a beat\nLower slowly against the pad",
  },
  calfRaise: {
    exerciseId: "ex-standing-calf-raise",
    name: "Standing Calf Raise",
    primaryMuscle: "CALVES",
    secondaryMuscles: [],
    exerciseType: "ISOLATION",
    measurementType: "REPS",
    targetReps: "15-20",
    targetDurationSeconds: null,
    restSeconds: 60,
    instructions:
      "Balls of the feet on the platform\nDrop the heels for a full stretch\nRise onto the toes and pause\nKeep the knees soft, not locked",
  },
} satisfies Record<string, LibraryEntry>;

type LibraryKey = keyof typeof LIBRARY;

/* ── Builders ── */

const today = () => new Date().toISOString().slice(0, 10);

function makeExercise(
  id: string,
  libraryKey: LibraryKey,
  phase: ExerciseCategory,
  sortOrder: number,
  targetSets: number,
): WorkoutExercise {
  const entry = LIBRARY[libraryKey];
  return {
    id,
    exerciseId: entry.exerciseId,
    exerciseName: entry.name,
    primaryMuscle: entry.primaryMuscle,
    secondaryMuscles: entry.secondaryMuscles,
    exerciseType: entry.exerciseType,
    measurementType: entry.measurementType,
    phase,
    sortOrder,
    targetSets,
    targetReps: entry.targetReps,
    targetDurationSeconds: entry.targetDurationSeconds,
    restSeconds: entry.restSeconds,
    notes: null,
    instructions: entry.instructions,
    thumbnailKey: null,
    videoKey: null,
    sets: [],
  };
}

function seedWorkout(): Workout {
  return {
    id: "w-today",
    date: today(),
    targetMuscle: "CHEST",
    totalDurationMinutes: 45,
    status: "PLANNED",
    exercises: [
      makeExercise("we-1", "armCircles", "WARMUP", 0, 1),
      makeExercise("we-2", "benchPress", "MAIN", 0, 3),
      makeExercise("we-3", "inclinePress", "MAIN", 1, 3),
      makeExercise("we-4", "treadmill", "MAIN", 2, 2),
      makeExercise("we-5", "chestStretch", "STRETCHING", 0, 1),
    ],
  };
}

/** A swapped workout gets a new id, mirroring the backend creating a new row. */
function seedSwappedWorkout(id: string, muscle: MuscleGroup): Workout {
  return {
    id,
    date: today(),
    targetMuscle: muscle,
    totalDurationMinutes: 40,
    status: "PLANNED",
    exercises: [
      makeExercise("we-swap-1", "legPress", "MAIN", 0, 3),
      makeExercise("we-swap-2", "hamstringCurl", "MAIN", 1, 3),
      makeExercise("we-swap-3", "calfRaise", "MAIN", 2, 3),
    ],
  };
}

/* ── In-memory store ── */

type MockDb = {
  workout: Workout;
  nextSetId: number;
  nextAddedId: number;
  swapCount: number;
  failComplete: boolean;
};

const globalForMock = globalThis as typeof globalThis & {
  __flexfitMockDb?: MockDb;
};

const ALTERNATE_MUSCLES: AlternateMuscle[] = [
  { splitDayIndex: 1, name: "Push", muscle: "CHEST", targetMuscles: ["CHEST", "TRICEPS"] },
  { splitDayIndex: 2, name: "Pull", muscle: "BACK", targetMuscles: ["BACK", "BICEPS"] },
  { splitDayIndex: 3, name: "Legs", muscle: "LEGS", targetMuscles: ["LEGS", "GLUTES"] },
];

const ALTERNATIVE_KEYS: LibraryKey[] = ["benchPress", "inclinePress", "chestStretch"];

/**
 * Lives on `globalThis` so Next's dev-mode module reload doesn't wipe logged
 * sets halfway through a review.
 */
export function getDb(): MockDb {
  globalForMock.__flexfitMockDb ??= {
    workout: seedWorkout(),
    nextSetId: 1,
    nextAddedId: 1,
    swapCount: 0,
    failComplete: MOCK_FAIL === "complete",
  };
  return globalForMock.__flexfitMockDb;
}

export function resetDb(): MockDb {
  globalForMock.__flexfitMockDb = {
    workout: seedWorkout(),
    nextSetId: 1,
    nextAddedId: 1,
    swapCount: 0,
    failComplete: MOCK_FAIL === "complete",
  };
  return globalForMock.__flexfitMockDb;
}

export function setFailComplete(fail: boolean): boolean {
  getDb().failComplete = fail;
  return fail;
}

/* ── Queries ── */

export const todayWorkout = (): Workout => getDb().workout;

export const alternateMuscles = (): AlternateMuscle[] => ALTERNATE_MUSCLES;

export function alternatives(): WorkoutExercise[] {
  return ALTERNATIVE_KEYS.map((key, index) =>
    makeExercise(`alt-${index + 1}`, key, "MAIN", index, 3),
  );
}

/* ── Mutations ── */

export function swapWorkout(muscle: string): Workout {
  const db = getDb();
  db.swapCount += 1;
  db.workout = seedSwappedWorkout(
    `w-today-swapped-${db.swapCount}`,
    (muscle as MuscleGroup) ?? "LEGS",
  );
  return db.workout;
}

export function addExercises(exerciseIds: string[]): Workout {
  const db = getDb();
  const known = new Set(Object.values(LIBRARY).map((entry) => entry.exerciseId));

  exerciseIds
    .filter((id) => known.has(id))
    .forEach((id, index) => {
      const key = (Object.keys(LIBRARY) as LibraryKey[]).find(
        (k) => LIBRARY[k].exerciseId === id,
      );
      if (!key) return;
      db.nextAddedId += 1;
      db.workout.exercises.push(
        makeExercise(`we-added-${db.nextAddedId}`, key, "MAIN", 90 + index, 3),
      );
    });

  return db.workout;
}

export function replaceExercise(
  exerciseId: string,
  alternativeId: string,
): Workout | null {
  const db = getDb();
  const exercise = db.workout.exercises.find((ex) => ex.id === exerciseId);
  const key = (Object.keys(LIBRARY) as LibraryKey[]).find(
    (k) => LIBRARY[k].exerciseId === alternativeId,
  );
  if (!exercise || !key) return null;

  const entry = LIBRARY[key];
  exercise.exerciseId = entry.exerciseId;
  exercise.exerciseName = entry.name;
  exercise.primaryMuscle = entry.primaryMuscle;
  exercise.secondaryMuscles = entry.secondaryMuscles;
  exercise.exerciseType = entry.exerciseType;
  exercise.measurementType = entry.measurementType;
  exercise.targetReps = entry.targetReps;
  exercise.targetDurationSeconds = entry.targetDurationSeconds;
  exercise.restSeconds = entry.restSeconds;
  exercise.instructions = entry.instructions;

  return db.workout;
}

export function deleteExercise(exerciseId: string): Workout | null {
  const db = getDb();
  const before = db.workout.exercises.length;
  db.workout.exercises = db.workout.exercises.filter((ex) => ex.id !== exerciseId);
  return db.workout.exercises.length === before ? null : db.workout;
}

export function logSet(
  exerciseId: string,
  input: WorkoutSetInput,
): WorkoutSet | null {
  const db = getDb();
  const exercise = db.workout.exercises.find((ex) => ex.id === exerciseId);
  if (!exercise) return null;

  const set: WorkoutSet = {
    id: `set-${db.nextSetId}`,
    setNumber: input.setNumber,
    weight: input.weight ?? null,
    reps: input.reps ?? null,
    distance: input.distance ?? null,
    durationSeconds: input.durationSeconds ?? null,
    notes: input.notes ?? null,
  };

  db.nextSetId += 1;
  exercise.sets.push(set);
  return set;
}

export function deleteSet(exerciseId: string, setId: string): boolean {
  const db = getDb();
  const exercise = db.workout.exercises.find((ex) => ex.id === exerciseId);
  if (!exercise) return false;
  const before = exercise.sets.length;
  exercise.sets = exercise.sets.filter((set) => set.id !== setId);
  return exercise.sets.length !== before;
}

export function completeWorkout(): Workout | null {
  const db = getDb();
  if (db.failComplete) return null;
  db.workout.status = "COMPLETED";
  return db.workout;
}

/* ── Introspection (reviewer tooling) ── */

export function dbSnapshot() {
  const db = getDb();
  return {
    workoutId: db.workout.id,
    date: db.workout.date,
    status: db.workout.status,
    failComplete: db.failComplete,
    exercises: db.workout.exercises.map((ex) => ({
      id: ex.id,
      name: ex.exerciseName,
      phase: ex.phase,
      targetSets: ex.targetSets,
      loggedSets: ex.sets.length,
      setNumbers: ex.sets.map((set) => set.setNumber),
    })),
  };
}

import type { NextRequest } from "next/server";

import { USE_MOCKS } from "@/lib/mock/config";
import * as db from "@/lib/mock/db";
import type { WorkoutSetInput } from "@/types/workout";

/**
 * Fixture API for `NEXT_PUBLIC_USE_MOCKS=1`.
 *
 * Same shape as the Spring backend: every response is the standard envelope
 * `{ success, status, message, data, timestamp }`, which `lib/api.ts` unwraps.
 * When the flag is off every route 404s, so this file is inert in production.
 */

export const dynamic = "force-dynamic";

type Ctx = { params: Promise<{ path: string[] }> };
type Method = "GET" | "POST" | "PUT" | "DELETE";

const envelope = <T,>(data: T, status = 200, message = "OK") => ({
  success: status < 400,
  status,
  message,
  data: status < 400 ? data : null,
  timestamp: new Date().toISOString(),
});

const ok = <T,>(data: T) => Response.json(envelope(data));
const bad = (message: string, status = 400) =>
  Response.json(envelope(null, status, message), { status });

const asRecord = (value: unknown): Record<string, unknown> =>
  typeof value === "object" && value !== null
    ? (value as Record<string, unknown>)
    : {};

const num = (value: unknown): number | null =>
  typeof value === "number" && Number.isFinite(value) ? value : null;

function toSetInput(raw: Record<string, unknown>): WorkoutSetInput {
  return {
    setNumber: num(raw.setNumber) ?? 1,
    weight: num(raw.weight),
    reps: num(raw.reps),
    distance: num(raw.distance),
    durationSeconds: num(raw.durationSeconds),
    notes: typeof raw.notes === "string" ? raw.notes : null,
  };
}

async function handle(
  method: Method,
  req: NextRequest,
  ctx: Ctx,
): Promise<Response> {
  if (!USE_MOCKS) {
    return bad(
      "Mock mode is off. Start the app with NEXT_PUBLIC_USE_MOCKS=1.",
      404,
    );
  }

  const { path } = await ctx.params;
  const route = path.join("/");
  const body =
    method === "POST" || method === "PUT"
      ? asRecord(await req.json().catch(() => null))
      : {};

  /* ── Auth: never fail, so nothing triggers the 401 → /login redirect ── */
  if (route.startsWith("auth/")) return ok(null);

  /* ── Profile: only onboarding/equipment-selection use it ── */
  if (method === "GET" && route === "profiles") {
    return ok({
      userId: "mock-user",
      name: "Mock Athlete",
      gender: "OTHER",
      dateOfBirth: null,
      height: 175,
      weight: 75,
      fitnessGoal: "GAIN_MUSCLE",
      experienceLevel: "INTERMEDIATE",
      workoutDaysPerWeek: 4,
      workoutDurationMinutes: 45,
      workoutEnvironment: "GYM",
      workoutSplit: "UPPER_LOWER",
      profileComplete: true,
    });
  }

  /* ── Reviewer tooling ── */
  if (method === "GET" && route === "__mock/state") {
    return ok(db.dbSnapshot());
  }
  if (method === "POST" && route === "__mock/fail") {
    const fail =
      typeof body.fail === "boolean"
        ? body.fail
        : !db.getDb().failComplete;
    return ok({ failComplete: db.setFailComplete(fail) });
  }
  if (method === "POST" && route === "__mock/reset") {
    db.resetDb();
    return ok(db.dbSnapshot());
  }

  /* ── Workouts ── */
  if (method === "GET" && route === "workouts/today") {
    return ok(db.todayWorkout());
  }

  if (method === "GET" && route === "workouts/today/alternate-muscles") {
    return ok(db.alternateMuscles());
  }

  if (method === "POST" && route === "workouts/today/swap") {
    return ok(db.swapWorkout(String(body.muscle ?? "LEGS")));
  }

  if (method === "GET" && /^workouts\/[^/]+\/alternatives$/.test(route)) {
    return ok(db.alternatives());
  }

  const complete = route.match(/^workouts\/([^/]+)\/complete$/);
  if (method === "POST" && complete) {
    const workout = db.completeWorkout();
    if (!workout) {
      return bad("Could not complete workout — try again.", 500);
    }
    return ok(workout);
  }

  const setCollection = route.match(
    /^workouts\/([^/]+)\/exercises\/([^/]+)\/sets$/,
  );
  if (method === "POST" && setCollection) {
    const set = db.logSet(setCollection[2], toSetInput(body));
    return set ? ok(set) : bad("Unknown exercise", 404);
  }

  const setItem = route.match(
    /^workouts\/([^/]+)\/exercises\/([^/]+)\/sets\/([^/]+)$/,
  );
  if (method === "DELETE" && setItem) {
    return db.deleteSet(setItem[2], setItem[3])
      ? ok(null)
      : bad("Unknown set", 404);
  }

  const replace = route.match(
    /^workouts\/([^/]+)\/exercises\/([^/]+)\/replace\/([^/]+)$/,
  );
  if (method === "PUT" && replace) {
    const workout = db.replaceExercise(replace[2], replace[3]);
    return workout ? ok(workout) : bad("Unknown exercise", 404);
  }

  const exerciseItem = route.match(/^workouts\/([^/]+)\/exercises\/([^/]+)$/);
  if (method === "DELETE" && exerciseItem) {
    const workout = db.deleteExercise(exerciseItem[2]);
    return workout ? ok(workout) : bad("Unknown exercise", 404);
  }

  const exerciseCollection = route.match(/^workouts\/([^/]+)\/exercises$/);
  if (method === "POST" && exerciseCollection) {
    const ids = Array.isArray(body.exerciseIds)
      ? body.exerciseIds.filter((id): id is string => typeof id === "string")
      : [];
    return ok(db.addExercises(ids));
  }

  return bad(`No fixture for ${method} /api/v1/${route}`, 404);
}

export const GET = (req: NextRequest, ctx: Ctx) => handle("GET", req, ctx);
export const POST = (req: NextRequest, ctx: Ctx) => handle("POST", req, ctx);
export const PUT = (req: NextRequest, ctx: Ctx) => handle("PUT", req, ctx);
export const DELETE = (req: NextRequest, ctx: Ctx) => handle("DELETE", req, ctx);

"use client";

import { useCallback, useEffect, useState } from "react";
import { motion } from "motion/react";
import { FlaskConical, RotateCcw, Timer, Trash2 } from "lucide-react";

import { USE_MOCKS } from "@/lib/mock/config";
import { workoutService } from "@/services/workoutService";
import type { Workout } from "@/types/workout";

/**
 * Reviewer tooling for `NEXT_PUBLIC_USE_MOCKS=1`.
 *
 * Seeds `flexfit.session` with the exact blob a force-kill would leave behind,
 * so the overnight bug can be reproduced in seconds instead of hours. Always
 * hard-navigates afterwards: client-side routing keeps the in-memory store and
 * would mask the rehydration path.
 */

const SESSION_KEY = "flexfit.session";
const MINUTE = 60_000;
const HOUR = 60 * MINUTE;

type Seed = {
  status: "idle" | "running" | "paused" | "completed";
  workoutId: string;
  date: string;
  startedAt: number;
  completedAt: null;
  accumulatedMs: number;
  runningSince: number | null;
  skippedExerciseIds: string[];
  completedExerciseIds: string[];
  rest: null | {
    endsAt: number | null;
    remainingMs: number;
    durationSeconds: number;
    next: { exerciseId: string; setNumber: number } | null;
    catchUpExerciseId: string | null;
    completedExerciseId: string | null;
  };
  /** Forward-compatible: current code ignores it, a heartbeat fix will read it. */
  lastSeenAt?: number;
};

function writeSession(state: Seed) {
  localStorage.setItem(
    SESSION_KEY,
    JSON.stringify({ state, version: 1 }),
  );
  window.location.assign("/workout");
}

export default function MockSeedPage() {
  const [workout, setWorkout] = useState<Workout | null>(null);
  const [failComplete, setFailComplete] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [dump, setDump] = useState("");

  const refresh = useCallback(async () => {
    setError(null);
    try {
      const current = await workoutService.getTodayWorkout();
      setWorkout(current);

      const res = await fetch("/api/v1/__mock/state");
      const json = (await res.json()) as { data?: { failComplete?: boolean } };
      setFailComplete(!!json.data?.failComplete);

      setDump(localStorage.getItem(SESSION_KEY) ?? "(nothing stored)");
    } catch {
      setError("Could not reach the fixture API. Is NEXT_PUBLIC_USE_MOCKS=1 set?");
    }
  }, []);

  useEffect(() => {
    if (!USE_MOCKS) return;
    void refresh();
  }, [refresh]);

  const seed = (build: (workout: Workout) => Seed) => {
    if (!workout) return;
    writeSession(build(workout));
  };

  const toggleFail = async () => {
    const res = await fetch("/api/v1/__mock/fail", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ fail: !failComplete }),
    });
    const json = (await res.json()) as { data?: { failComplete?: boolean } };
    setFailComplete(!!json.data?.failComplete);
  };

  const resetFixtures = async () => {
    await fetch("/api/v1/__mock/reset", { method: "POST" });
    localStorage.removeItem(SESSION_KEY);
    await refresh();
  };

  if (!USE_MOCKS) {
    return (
      <div className="min-h-dvh bg-background text-foreground px-6 pt-14">
        <h1 className="font-display text-2xl font-bold">Mock mode is off</h1>
        <p className="mt-2 text-sm text-muted-foreground">
          Restart with{" "}
          <code className="rounded bg-secondary px-1.5 py-0.5">
            NEXT_PUBLIC_USE_MOCKS=1 bun dev
          </code>
        </p>
      </div>
    );
  }

  const mainExercise =
    workout?.exercises.find((ex) => ex.phase === "MAIN") ??
    workout?.exercises[0];

  return (
    <div className="min-h-dvh bg-background text-foreground px-6 pt-14 pb-16">
      <div className="flex items-center gap-2 text-primary">
        <FlaskConical size={16} />
        <span className="text-[10px] uppercase tracking-[0.2em] font-semibold">
          Fixtures
        </span>
      </div>
      <h1 className="mt-2 font-display text-2xl font-bold">Session scenarios</h1>
      <p className="mt-1 text-sm text-muted-foreground">
        Writes <code className="rounded bg-secondary px-1 py-0.5">flexfit.session</code>{" "}
        and reloads. Clear between runs.
      </p>

      {error && (
        <p className="mt-4 rounded-2xl border border-destructive/40 bg-card p-3 text-xs text-destructive">
          {error}
        </p>
      )}

      <div className="mt-6 flex flex-col gap-3">
        <Scenario
          title="Overnight — 14h away after 45 min"
          detail="Expect: a few minutes at most, paused. A 14h clock means the bug is still there."
          onClick={() =>
            seed((w) => {
              const now = Date.now();
              return {
                status: "running",
                workoutId: w.id,
                date: w.date,
                startedAt: now - 14 * HOUR,
                completedAt: null,
                accumulatedMs: 0,
                runningSince: now - 14 * HOUR,
                lastSeenAt: now - 14 * HOUR + 45 * MINUTE,
                skippedExerciseIds: [],
                completedExerciseIds: [],
                rest: null,
              };
            })
          }
        />

        <Scenario
          title="Quick switch — away 30s"
          detail="Expect: still running, roughly 30s added. This is the grace window."
          onClick={() =>
            seed((w) => {
              const now = Date.now();
              return {
                status: "running",
                workoutId: w.id,
                date: w.date,
                startedAt: now - 30 * MINUTE,
                completedAt: null,
                accumulatedMs: 0,
                runningSince: now - 30 * MINUTE,
                lastSeenAt: now - 5_000,
                skippedExerciseIds: [],
                completedExerciseIds: [],
                rest: null,
              };
            })
          }
        />

        <Scenario
          title="Paused — 47 min banked"
          detail="Baseline: the paused state should survive a reload untouched."
          onClick={() =>
            seed((w) => {
              const now = Date.now();
              return {
                status: "paused",
                workoutId: w.id,
                date: w.date,
                startedAt: now - 2 * HOUR,
                completedAt: null,
                accumulatedMs: 47 * MINUTE,
                runningSince: null,
                skippedExerciseIds: [],
                completedExerciseIds: [],
                rest: null,
              };
            })
          }
        />

        <Scenario
          title="Mid-rest — 2.5s left"
          detail="Expect: the rest screen resolves itself with no tap, even after a reload."
          onClick={() =>
            seed((w) => {
              const now = Date.now();
              const next = w.exercises[1] ?? w.exercises[0];
              return {
                status: "running",
                workoutId: w.id,
                date: w.date,
                startedAt: now - 10 * MINUTE,
                completedAt: null,
                accumulatedMs: 0,
                runningSince: now - 10 * MINUTE,
                skippedExerciseIds: [],
                completedExerciseIds: [],
                rest: {
                  endsAt: now + 2_500,
                  remainingMs: 2_500,
                  durationSeconds: 90,
                  next: { exerciseId: next.id, setNumber: next.sets.length + 1 },
                  catchUpExerciseId: null,
                  completedExerciseId: null,
                },
              };
            })
          }
        />

        <Scenario
          title="Clear session"
          detail="Removes flexfit.session so the next scenario starts clean."
          icon={<Trash2 size={16} />}
          onClick={() => {
            localStorage.removeItem(SESSION_KEY);
            window.location.assign("/workout");
          }}
        />
      </div>

      <h2 className="mt-10 font-display text-lg font-bold">Failure injection</h2>
      <p className="mt-1 text-sm text-muted-foreground">
        Makes <code className="rounded bg-secondary px-1 py-0.5">POST /complete</code>{" "}
        return a 500. Finish a workout and watch what the UI does.
      </p>
      <button
        onClick={() => void toggleFail()}
        className="mt-3 w-full rounded-2xl border border-border bg-card px-4 py-3 text-left text-sm font-semibold"
      >
        Complete endpoint:{" "}
        <span className={failComplete ? "text-destructive" : "text-primary"}>
          {failComplete ? "failing" : "healthy"}
        </span>
      </button>

      <h2 className="mt-10 font-display text-lg font-bold">Current fixtures</h2>
      <p className="mt-1 text-sm text-muted-foreground">
        Workout {workout?.id ?? "—"}
        {mainExercise ? ` · first exercise ${mainExercise.id}` : ""}
      </p>
      <pre className="mt-3 max-h-64 overflow-auto rounded-2xl border border-border bg-card p-3 text-[11px] leading-relaxed text-muted-foreground">
        {dump}
      </pre>

      <div className="mt-6 flex flex-col gap-3">
        <button
          onClick={() => void refresh()}
          className="flex items-center justify-center gap-2 rounded-2xl bg-primary px-4 py-3 text-sm font-semibold text-primary-foreground"
        >
          <Timer size={16} />
          Refresh
        </button>
        <button
          onClick={() => void resetFixtures()}
          className="flex items-center justify-center gap-2 rounded-2xl border border-border bg-card px-4 py-3 text-sm font-semibold"
        >
          <RotateCcw size={16} />
          Reset fixtures and session
        </button>
      </div>
    </div>
  );
}

function Scenario({
  title,
  detail,
  onClick,
  icon,
}: {
  title: string;
  detail: string;
  onClick: () => void;
  icon?: React.ReactNode;
}) {
  return (
    <motion.button
      whileTap={{ scale: 0.98 }}
      onClick={onClick}
      className="rounded-2xl border border-border bg-card px-4 py-3 text-left"
    >
      <span className="flex items-center gap-2 text-sm font-semibold">
        {icon ?? <FlaskConical size={16} className="text-primary" />}
        {title}
      </span>
      <span className="mt-1 block text-[11px] leading-relaxed text-muted-foreground">
        {detail}
      </span>
    </motion.button>
  );
}

