import { chromium } from "playwright-core";

const BASE = "http://localhost:3100";
const browser = await chromium.launch({
  executablePath: "/usr/bin/google-chrome",
  args: ["--no-sandbox"],
});
const ctx = await browser.newContext({ viewport: { width: 390, height: 844 } });
const page = await ctx.newPage();

const external = new Set<string>();
const failures: string[] = [];
page.on("request", (r) => {
  const u = new URL(r.url());
  if (!["localhost", "127.0.0.1"].includes(u.hostname) && !u.protocol.startsWith("data")) {
    external.add(`${u.protocol}//${u.hostname}${u.pathname}`);
  }
});
page.on("requestfailed", (r) => failures.push(`${r.url()} — ${r.failure()?.errorText}`));
page.on("pageerror", (e) => failures.push(`pageerror: ${e.message}`));

await page.goto(`${BASE}/workout`, { waitUntil: "networkidle" });
await page.waitForTimeout(800);

const fonts = await page.evaluate(() => {
  const loaded = [...document.fonts].map((f) => `${f.family} ${f.weight} ${f.status}`);
  const body = getComputedStyle(document.body).fontFamily;
  const display = getComputedStyle(
    document.querySelector(".font-display") ?? document.body,
  ).fontFamily;
  return { loaded, body, display };
});
console.log("document.fonts:", JSON.stringify(fonts.loaded));
console.log("body font  :", fonts.body);
console.log("display font:", fonts.display);

/* session bar on /exercise, which is where elapsed time lives */
await page.goto(`${BASE}/dev/seed`, { waitUntil: "networkidle" });
await page.click("text=Overnight — 14h away after 45 min");
await page.waitForURL(/\/workout$/);
await page.waitForLoadState("networkidle");
const workoutText = (await page.textContent("body")) ?? "";
const shown = workoutText.replace(/\s+/g, " ").match(/\d{1,2}:\d{2}(?::\d{2})?/g) ?? [];
console.log("overnight clock on /workout:", JSON.stringify(shown));

await page.goto(`${BASE}/exercise?exerciseId=we-2`, { waitUntil: "networkidle" });
await page.waitForTimeout(500);
const exText = (await page.textContent("body")) ?? "";
const exTimes = exText.replace(/\s+/g, " ").match(/\d{1,2}:\d{2}(?::\d{2})?/g) ?? [];
console.log("clock on /exercise:", JSON.stringify(exTimes.slice(0, 4)));

console.log("external requests:", JSON.stringify([...external]));
console.log("failed requests:", JSON.stringify(failures.slice(0, 5)));
await browser.close();

