import { chromium } from "playwright-core";

const BASE = "http://localhost:3100";
const browser = await chromium.launch({
  executablePath: "/usr/bin/google-chrome",
  args: ["--no-sandbox"],
});
const ctx = await browser.newContext({ viewport: { width: 390, height: 844 } });
const page = await ctx.newPage();
page.on("pageerror", (e) => console.log("pageerror:", e.message));

const state = async () => {
  const r = await page.request.get(`${BASE}/api/v1/__mock/state`);
  return (await r.json()).data;
};
const setFail = (fail: boolean) =>
  page.request.post(`${BASE}/api/v1/__mock/fail`, { data: { fail } });
const reset = () => page.request.post(`${BASE}/api/v1/__mock/reset`);

async function run(fail: boolean) {
  await reset();
  await setFail(fail);
  await page.goto(`${BASE}/dev/seed`, { waitUntil: "networkidle" });
  await page.click("text=Almost done — one exercise left");
  await page.waitForURL(/\/workout$/);
  await page.waitForLoadState("networkidle");

  const href0 = new URL(page.url()).pathname;
  await page.click("text=Resume workout");
  await page.waitForURL(/\/exercise\?/, { timeout: 10_000 });
  const href1 = new URL(page.url());
  console.log(`[fail=${fail}] resume ->`, href1.pathname + href1.search);

  await page.click('button[aria-label="Mark exercise done"]');
  await page.waitForURL(/\/complete$/, { timeout: 15_000 }).catch(() => {});
  await page.waitForTimeout(1200);

  const href2 = new URL(page.url()).pathname;
  const s = await state();
  const stored = await page.evaluate(() => localStorage.getItem("flexfit.session"));
  console.log(`[fail=${fail}] after Done ->`, href2);
  console.log(`[fail=${fail}] fixture status:`, s.status);
  console.log(`[fail=${fail}] session in storage:`, stored === null ? "cleared" : stored.slice(0, 60));
  console.log(`[fail=${fail}] visible error text:`,
    (await page.textContent("body"))?.match(/couldn.t|failed|error|try again/i)?.[0] ?? "none");
  console.log("");
  return { href0, href2, status: s.status, stored };
}

await run(false);
await run(true);
await reset();
await browser.close();

