import { afterEach, beforeEach, describe, expect, setSystemTime, test } from "bun:test";

/**
 * The store is browser code: `persist` reaches for `localStorage` on every
 * `set()`. Bun has no DOM, so give it the smallest thing that behaves like one
 * before importing the module.
 */
const memory = new Map<string, string>();
Object.defineProperty(globalThis, "localStorage", {
  configurable: true,
  value: {
    getItem: (key: string) => memory.get(key) ?? null,
    setItem: (key: string, value: string) => void memory.set(key, String(value)),
    removeItem: (key: string) => void memory.delete(key),
    clear: () => memory.clear(),
    key: (index: number) => [...memory.keys()][index] ?? null,
    get length() {
      return memory.size;
    },
  },
});

const { sessionElapsedMs, useSessionStore } = await import(
  "@/store/sessionStore"
);

const MINUTE = 60_000;
const T0 = new Date("2026-01-01T10:00:00.000Z");

const elapsed = () => sessionElapsedMs(useSessionStore.getState());

beforeEach(() => {
  setSystemTime(T0);
  memory.clear();
  useSessionStore.getState().clear();
});

afterEach(() => {
  setSystemTime();
});

describe("session clock", () => {
  test("a new session starts at zero and runs", () => {
    useSessionStore.getState().start("w-1", "2026-01-01");

    const state = useSessionStore.getState();
    expect(state.status).toBe("running");
    expect(state.runningSince).not.toBeNull();
    expect(elapsed()).toBe(0);

    setSystemTime(new Date(T0.getTime() + 5 * MINUTE));
    expect(elapsed()).toBe(5 * MINUTE);
