/**
 * Reviewer oracle for bug 1. Not part of the repo handed to the agent.
 *
 * Copy into the agent's checkout as `store/review.test.ts`, then:
 *
 *   bun test store/review.test.ts
 *   rm store/review.test.ts
 *
 * It has to live inside the repo so `@/` resolves and Bun picks up tsconfig
 * paths. It imports the real store, writes the exact blob the current release
 * persists (`version: 1`, no extra fields), and reads back the clock.
 *
 * Why it works this way: a v1 blob only records when the session *started*
 * running, not when the app died, so a correct fix can only cap the unproven
 * part of the gap. The assertions are therefore a band, not an exact number:
 * a short gap counts, a long one does not, and a paused session is untouched.
 */

import {
  afterEach,
  beforeEach,
  describe,
  expect,
  setSystemTime,
  test,
} from "bun:test";

const KEY = "flexfit.session";
const MIN = 60_000;
const HOUR = 60 * MIN;
const GRACE_CEILING = 125_000; // "up to two minutes", plus 5s of slack

const storage = new Map<string, string>();
const memory = {
  getItem: (key: string) => storage.get(key) ?? null,
  setItem: (key: string, value: string) => void storage.set(key, String(value)),
  removeItem: (key: string) => void storage.delete(key),
  clear: () => storage.clear(),
  key: (index: number) => [...storage.keys()][index] ?? null,
  get length() {
    return storage.size;
  },
};

Object.defineProperty(globalThis, "window", {
  configurable: true,
  value: { localStorage: memory },
});
Object.defineProperty(globalThis, "localStorage", {
  configurable: true,
  value: memory,
});

const { useSessionStore } = await import("@/store/sessionStore");

const NOW = new Date("2026-03-01T09:00:00.000Z").getTime();

const FRESH = {
  status: "idle" as const,
  workoutId: null,
  date: null,
  startedAt: null,
  completedAt: null,
  accumulatedMs: 0,
  runningSince: null,
  skippedExerciseIds: [] as string[],
  completedExerciseIds: [] as string[],
  rest: null,
};

/** The shape this build actually writes: partialize() output, nothing else. */
function v1(overrides: Record<string, unknown> = {}) {
  return {
    status: "running",
    workoutId: "w-1",
    date: "2026-03-01",
    startedAt: NOW - HOUR,
    completedAt: null,
    accumulatedMs: 0,
    runningSince: NOW - HOUR,
    skippedExerciseIds: [],
    completedExerciseIds: [],
    rest: null,
    ...overrides,
  };
}

/** Fresh page load: empty memory, blob on disk, then rehydrate. */
async function boot(blob: Record<string, unknown>) {
  useSessionStore.setState(FRESH);
  storage.set(KEY, JSON.stringify({ state: blob, version: 1 }));
  await useSessionStore.persist.rehydrate();
}

function elapsedMs() {
  const s = useSessionStore.getState();
  return s.accumulatedMs + (s.runningSince === null ? 0 : Date.now() - s.runningSince);
}

function secondsAfterBoot(blob: Record<string, unknown>) {
  return elapsedMs() / 1000;
}

beforeEach(() => {
  setSystemTime(new Date(NOW));
  storage.clear();
  useSessionStore.setState(FRESH);
});

afterEach(() => {
  setSystemTime();
});

describe("bug 1 — clock must not count time the app was closed", () => {
  test("14h gap after 45 min of work does not read as a 14h workout", async () => {
    await boot(
      v1({
        startedAt: NOW - 14 * HOUR,
        runningSince: NOW - 14 * HOUR,
      }),
    );

    const s = useSessionStore.getState();
    console.log(`   -> elapsed ${(elapsedMs() / 1000).toFixed(1)}s, status ${s.status}`);

    expect(elapsedMs()).toBeLessThanOrEqual(GRACE_CEILING);
    expect(elapsedMs()).toBeGreaterThanOrEqual(0);
    // 14h < 24h, so the workout is still today's and must stay resumable.
    expect(s.workoutId).toBe("w-1");
  });

  test("a 30s app switch keeps the seconds", async () => {
    await boot(v1({ startedAt: NOW - 30_000, runningSince: NOW - 30_000 }));

    console.log(`   -> elapsed ${(elapsedMs() / 1000).toFixed(1)}s`);
    expect(elapsedMs()).toBeGreaterThanOrEqual(25_000);
    expect(elapsedMs()).toBeLessThanOrEqual(GRACE_CEILING);
  });

  test("a 3 min gap is capped, not banked in full", async () => {
    await boot(v1({ startedAt: NOW - 3 * MIN, runningSince: NOW - 3 * MIN }));

    console.log(`   -> elapsed ${(elapsedMs() / 1000).toFixed(1)}s`);
    expect(elapsedMs()).toBeLessThanOrEqual(GRACE_CEILING);
  });

  test("a paused session reloads exactly as it was stored", async () => {
    await boot(
      v1({
        status: "paused",
        startedAt: NOW - 2 * HOUR,
        accumulatedMs: 47 * MIN,
        runningSince: null,
      }),
    );

    const s = useSessionStore.getState();
    console.log(`   -> ${(elapsedMs() / 60_000).toFixed(2)} min, status ${s.status}`);
    expect(elapsedMs()).toBe(47 * MIN);
    expect(s.status).toBe("paused");
  });

  test("elapsed never goes backwards across a reload", async () => {
    await boot(
      v1({
        status: "paused",
        startedAt: NOW - 3 * HOUR,
        accumulatedMs: 12 * MIN,
        runningSince: null,
      }),
    );
    const before = elapsedMs();
    expect(before).toBe(12 * MIN);

    // Reload again with no new activity.
    setSystemTime(new Date(NOW + 5 * MIN));
    await boot(v1({ status: "paused", startedAt: NOW - 3 * HOUR, accumulatedMs: 12 * MIN, runningSince: null }));
    expect(elapsedMs()).toBeGreaterThanOrEqual(before);
  });
});

describe("regression — the clock still behaves", () => {
  test("a fresh session starts at zero", async () => {
    useSessionStore.setState(FRESH);
    useSessionStore.getState().start("w-2", "2026-03-01");

    expect(elapsedMs()).toBe(0);
    expect(useSessionStore.getState().status).toBe("running");

    setSystemTime(new Date(NOW + 4 * MIN));
    expect(elapsedMs()).toBe(4 * MIN);
  });

  test("pausing still banks the exact elapsed time", async () => {
    useSessionStore.setState(FRESH);
    useSessionStore.getState().start("w-3", "2026-03-01");
    setSystemTime(new Date(NOW + 9 * MIN));
    useSessionStore.getState().pause();

    expect(elapsedMs()).toBe(9 * MIN);
    setSystemTime(new Date(NOW + 40 * MIN));
    expect(elapsedMs()).toBe(9 * MIN);
  });
});

