/**
 * The store is browser code: `persist` reaches for `window.localStorage` on
 * every `set()`. Bun has no DOM, so give it the smallest thing that behaves
 * like one before importing the module. `window` has to exist too — Zustand's
 * default storage reads it through `window`, not through the bare global.
 *
 * Shared rather than per-file: Zustand captures `window.localStorage` when the
 * store module is first imported, so a second test file that installed its own
 * shim would write somewhere the first file cannot see. Whoever gets here first
 * wins and everybody else reuses it.
 */
function ensureLocalStorage() {
  const existing = (globalThis as { window?: { localStorage?: Storage } })
    .window?.localStorage;
  if (existing) return existing;

  const memory = new Map<string, string>();
  const storage = {
    getItem: (key: string) => memory.get(key) ?? null,
    setItem: (key: string, value: string) => void memory.set(key, String(value)),
    removeItem: (key: string) => void memory.delete(key),
    clear: () => memory.clear(),
    key: (index: number) => [...memory.keys()][index] ?? null,
    get length() {
      return memory.size;
    },
  };

  Object.defineProperty(globalThis, "window", {
    configurable: true,
    value: { localStorage: storage },
  });
  Object.defineProperty(globalThis, "localStorage", {
    configurable: true,
    value: storage,
  });

  return storage;
}

const storage = ensureLocalStorage();

