page.on("pageerror", (e) => console.log("  pageerror:", e.message));

async function scenario(name: string) {
  await page.goto(`${target}/dev/seed`, { waitUntil: "networkidle" });
  await page.click(`text=${name}`);
  await page.waitForURL(/\/workout$/);
  await page.waitForLoadState("networkidle");
  await page.waitForTimeout(600);
  const text = ((await page.textContent("body")) ?? "").replace(/\s+/g, " ");
  const clock = text.match(/\d{1,2}:\d{2}(?::\d{2})?/g)?.[0] ?? "—";
  const resume = text.includes("Resume workout");
  const start = text.includes("Start Workout");
  console.log(
    `  ${name.padEnd(36)} clock=${clock.padEnd(9)} resume=${String(resume).padEnd(5)} start=${start}`,
  );
}

