"use client";

import { motion } from "motion/react";
import { Pause, Play } from "lucide-react";

import { useSessionClock } from "@/hooks/useSession";
import { formatSessionTime } from "@/lib/session";
import { useSessionStore } from "@/store/sessionStore";

/**
 * Whole-workout elapsed time. The pill doubles as the pause control, since
 * that is the clock the user wants to stop.
 */
export default function SessionClock({ className }: { className?: string }) {
  const { status, elapsedMs } = useSessionClock();
  const pause = useSessionStore((s) => s.pause);
  const resume = useSessionStore((s) => s.resume);

  const paused = status === "paused";
  const active = status === "running" || paused;

  if (!active) return null;

  return (
    <motion.button
      whileTap={{ scale: 0.94 }}
      onClick={(event) => {
        event.stopPropagation();
        if (paused) resume();
        else pause();
      }}
      aria-label={paused ? "Resume workout timer" : "Pause workout timer"}
      className={`flex items-center gap-1.5 px-3 py-1.5 rounded-xl border backdrop-blur-md text-xs font-semibold tabular-nums cursor-pointer ${
        paused
          ? "bg-background/60 border-border text-muted-foreground"
          : "bg-background/60 border-primary/40 text-foreground"
      } ${className ?? ""}`}
    >
      {paused ? (
        <Play size={12} fill="currentColor" className="text-primary" />
      ) : (
        <Pause size={12} fill="currentColor" className="text-primary" />
      )}
      {formatSessionTime(elapsedMs)}
    </motion.button>
  );
}

"use client";

import { useEffect, useState } from "react";

import {
  restRemainingMs as remainingOf,
  sessionElapsedMs,
  useSessionStore,
} from "@/store/sessionStore";

/** Re-renders once a second so relative clocks stay live. */
function useTick(active: boolean) {
  const [, setTick] = useState(0);

  useEffect(() => {
    if (!active) return;
    const id = window.setInterval(() => setTick((t) => t + 1), 1000);
    return () => window.clearInterval(id);
  }, [active]);
}

/**
 * Elapsed workout time and rest countdown, refreshed every second while the
 * session runs. Both values are derived from timestamps, so nothing drifts.
 */
export function useSessionClock() {
  const status = useSessionStore((s) => s.status);
  const accumulatedMs = useSessionStore((s) => s.accumulatedMs);
  const runningSince = useSessionStore((s) => s.runningSince);
  const rest = useSessionStore((s) => s.rest);

  useTick(status === "running");

  const remaining = rest ? remainingOf(rest) : null;
  const total = rest ? rest.durationSeconds * 1000 : 0;

  return {
    status,
    elapsedMs: sessionElapsedMs({ accumulatedMs, runningSince }),
    restRemainingMs: remaining,
    /** 0 at the start of a rest, 1 when it is over. */
    restProgress: remaining !== null && total > 0 ? 1 - remaining / total : 0,
  };
}

