import { chromium } from "playwright-core";

const BASE = "http://localhost:3100";

const browser = await chromium.launch({
  executablePath: "/usr/bin/google-chrome",
  args: ["--no-sandbox"],
});

const context = await browser.newContext({ viewport: { width: 390, height: 844 } });
const page = await context.newPage();

async function runScenario(name: string) {
  await page.goto(`${BASE}/dev/seed`, { waitUntil: "networkidle" });
  await page.click(`text=${name}`);
  await page.waitForURL(/\/workout$/, { timeout: 15_000 });
  await page.waitForLoadState("networkidle");
  await page.waitForTimeout(600);

  const text = ((await page.textContent("body")) ?? "").replace(/\s+/g, " ");
  const clockMatches = text.match(/\d{1,2}:\d{2}(?::\d{2})?/g) ?? [];
  const hasResume = text.includes("Resume workout");
  const hasStart = text.includes("Start Workout");

  const stored = await page.evaluate(() => {
    const raw = localStorage.getItem("flexfit.session");
    if (!raw) return null;
    return JSON.parse(raw);
  });

  console.log(`\nScenario: "${name}"`);
  console.log(`  State in storage: status=${stored?.state?.status}, accumulatedMs=${stored?.state?.accumulatedMs}, runningSince=${stored?.state?.runningSince}`);
  console.log(`  UI clock: ${clockMatches[0] ?? "(none)"}`);
  console.log(`  UI buttons: Resume=${hasResume}, Start=${hasStart}`);
}

for (let i = 0; i < 30; i++) {
  try {
    const res = await fetch(`${BASE}/workout`);
    if (res.ok) break;
  } catch {}
  await new Promise((r) => setTimeout(r, 1000));
}

await runScenario("Overnight — 14h away after 45 min");
await runScenario("Stale — running for 30h");
await runScenario("Quick switch — 30 min in, 5 s away");
await runScenario("Paused — 47 min banked");
await runScenario("Mid-rest — 2.5s left");
await runScenario("Clear session");

await browser.close();

